from pathlib import Path
import html,re
P=Path
E=html.escape
css=re.search(r'<style>(.*?)</style>',P('index.html').read_text(encoding='utf-8'),re.S).group(1)
script=re.search(r'<script>.*?</script>',P('index.html').read_text(encoding='utf-8'),re.S).group(0)
a=['<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lab 2: Argo CD from install to automatic deployment</title><style>'+css+'.expected{background:#e9f4ed;padding:15px 20px;border-radius:10px}.checkpoint{font-weight:650;color:#27694f}.flow{font-size:20px;line-height:2}.optional{border:2px dashed #c7d8cf;padding:22px;margin:25px 0}.field{font-family:Consolas,monospace} .ui{background:#f5f0e5;border-radius:10px;padding:18px}</style><header><div class="eyebrow">LAB 2 / ARGO CD FOR BEGINNERS</div><h1>Install Argo CD.<br>Push a Git change.<br>Watch it deploy.</h1><p class="lead">One NGINX demo, one Application, one automatic delivery loop. Follow steps 1 to 6 for your classroom demo; learn self-healing and the CLI afterward.</p><div class="tags"><span>Git Bash + KillerCoda</span><span>Auto-sync from the start</span><span>Copyable manifests</span><span>Interview answers included</span></div><p><a href="index.html">Ingress lab</a> · <a href="environments.html">Environment help</a> · <a href="docs/ARGOCD-BEGINNER-TEST-RESULTS.md">Actual demo test results</a></p></header><main><nav>']
titles=['Deploy Argo CD first','Open the Argo CD URL','Create Deployment and Service manifests','Connect Git and write the Application','Let Argo deploy automatically','Demo: change replicas and configuration','Demo: repair a manual change','Use five simple CLI commands']
a += [f'<a href="#step{i}">{i}. {E(t)}</a>' for i,t in enumerate(titles,1)]
a += ['</nav><section><h2>The demo you will show</h2><p class="flow">Install Argo CD → save Kubernetes YAML in Git → create one Argo Application → automatic deployment → Git push → automatic reconciliation.</p><p><strong>No Lab 1 deployment is required for the beginner demo.</strong> You need a ready Kubernetes cluster, Git Bash or Linux Bash, kubectl, Helm, and a local clone of this repository. KillerCoda users can run <code>bash scripts/install-helm-linux.sh</code> first. Work from the repository root. If you already ran the older lab, its lab-nginx/lab-grafana/lab-prometheus tiles may remain; focus on the new <strong>demo-nginx</strong> tile.</p><img src="docs/argocd-beginner-flow.svg" alt="A Git commit changes Kubernetes manifests. The Argo CD Application connects repository, path and destination. Argo CD compares and applies them, creating a Service and two or three NGINX pods."></section>']
def start(n,text):a.append(f'<section id="step{n}"><span class="number">STEP {n}</span><h2>{titles[n-1]}</h2>{text}')
def code(label,text):a.append('<h3>'+E(label)+'</h3><div class="code"><button type="button">Copy</button><pre><code>'+E(text)+'</code></pre></div>')
def expected(text):a.append('<p class="expected"><strong>Expected:</strong> '+text+'</p>')
def qa(items):
 a.append('<h3>Interview questions and answers</h3>')
 for q,ans in items:a.append('<details class="interview" open><summary>'+E(q)+'</summary><p><strong>Answer:</strong> '+E(ans)+'</p></details>')
def end():a.append('</section>')
start(1,'<p>Install only the Argo CD control plane. Do not create an Application yet. This pinned Helm chart is already included in the repository, so no Helm repository download is needed. Argo uses HTTP only for this disposable learning setup. On Docker Desktop select the docker-desktop context; on KillerCoda keep its existing context.</p>')
code('Check the cluster and install Argo CD','export MSYS_NO_PATHCONV=1\nkubectl config current-context\nkubectl get nodes\nhelm upgrade --install argocd ./vendor/argo-cd-10.11.6.tgz -n argocd --create-namespace -f gitops/argocd-values.yaml --wait --timeout 10m\nkubectl get pods -n argocd')
expected('Argo CD server, application-controller, repo-server and Redis are Running. This installation creates no demo Application and no demo NGINX pods.')
qa([('What does Argo CD do?','It reads the desired Kubernetes configuration from Git, compares it with the cluster, and applies it according to the Application sync policy.'),('Which components matter for this demo?','The API server provides UI and CLI access. Repo-server reads Git. Application-controller compares and syncs resources. Redis provides caching.')]);end()
start(2,'<p>Keep terminal A open for the URL. Run all later commands in terminal B. The same helper works in Git Bash and KillerCoda: it forwards the Argo CD Service on port 8090 and prints the correct browser URL. No ingress controller or hosts-file change is needed to learn Argo CD.</p>')
code('Terminal A: open access to the UI','bash scripts/argocd-ui.sh')
a.append('<div class="ui"><strong>Docker Desktop:</strong> open <a href="http://localhost:8090">http://localhost:8090</a>.<br><strong>KillerCoda:</strong> open the URL printed by the helper, or Traffic / Ports → port 8090. The helper binds to the playground VM for that access.<br><strong>Username:</strong> admin. Read the password in terminal B below.</div>')
code('Terminal B: read the initial password',"kubectl get secret argocd-initial-admin-secret -n argocd -o jsonpath='{.data.password}' | base64 --decode\nprintf '\\n'")
a.append('<details><summary>What is the URL helper doing?</summary>')
code('Docker Desktop command used by the helper','kubectl port-forward -n argocd svc/argocd-server 8090:80 --address 127.0.0.1')
code('KillerCoda command used by the helper',"sed 's/PORT/8090/g' /etc/killercoda/host\nkubectl port-forward -n argocd svc/argocd-server 8090:80 --address 0.0.0.0")
a.append('</details>')
expected('You can sign in and see the Applications screen. Change the initial password after first login. If you changed it earlier, use your changed password.')
qa([('Does the UI URL deploy my app?','No. It only exposes the Argo server. An Application tells the controller which Git manifests to deploy.'),('Why does localhost not work in my laptop browser for KillerCoda?','The cluster runs on a remote VM. Use the platform-generated port 8090 URL in your laptop browser; localhost:8090 works inside the remote terminal for the CLI.')]);end()
start(3,'<p>Now define what Kubernetes should run. The Deployment creates two NGINX pods; the Service gives those pods a stable endpoint. These two files are already included. Expand the commands to see how to write them from scratch. <strong>Do not kubectl apply these workload files.</strong> Argo CD will deploy them from Git in step 5.</p>')
code('Inspect the two manifests','cat gitops/demo/manifests/deployment.yaml\ncat gitops/demo/manifests/service.yaml')
for file in ['deployment.yaml','service.yaml']:
 path=P('gitops/demo/manifests')/file
 a.append('<details open><summary>'+path.as_posix()+'</summary>')
 code('Create '+file, "mkdir -p gitops/demo/manifests\ncat > "+path.as_posix()+" <<'EOF'\n"+path.read_text(encoding='utf-8').rstrip()+"\nEOF")
 a.append('</details>')
a.append('<p><code>replicas: 2</code> is the desired pod count. The Deployment selector and pod label both use <code>app: demo-nginx</code>; the Service uses that same selector. The extra pod label <code>demo-version: v1</code> is a safe configuration-change demo: changing it later triggers a new rollout.</p>')
expected('The YAML files are present locally. At this point no new demo workload has been deployed.')
qa([('Deployment versus Service?','A Deployment maintains the desired pod replicas. A Service selects ready pods using labels and provides a stable network endpoint.'),('Why not apply the manifests manually?','For this exercise, Git is the desired-state source and Argo CD performs the deployment. Applying the workload directly would hide the automatic deployment we want to demonstrate.')]);end()
start(4,'<p>The Argo Application is the connection between Git and Kubernetes. It is different from a Deployment: it says <strong>where to read YAML, which branch to watch, where to deploy, and whether to sync automatically.</strong> Students should fork this repository first. The instructor can keep the existing vrdipu repository.</p>')
a.append('<h3>Connect your repository in the UI</h3><ol><li>Open <strong>Settings → Repositories → Connect Repo</strong>.</li><li>Choose <strong>HTTPS</strong>, type <strong>git</strong>, and enter your public GitHub repository URL.</li><li>Leave username/password empty for a public repository, then click <strong>Connect</strong>.</li><li>Confirm the connection is <strong>Successful</strong>.</li></ol><p>A public repository can also be read directly from the Application repoURL without registering it first. Connecting it here makes the Git connection visible during your lesson. GitHub push credentials on your laptop are separate from Argo CD’s read access.</p>')
code('Students: set your fork URL once',"git remote set-url origin https://github.com/YOUR-USERNAME/ingress-lab.git\nsed -i 's|repoURL: .*|repoURL: https://github.com/YOUR-USERNAME/ingress-lab.git|' gitops/demo/application.yaml")
a.append('<p>If you are the instructor working in vrdipu/ingress-lab, skip the fork command. Read the Application below, keeping your own repository URL in <code>spec.source.repoURL</code>.</p>')
code('The Application file: gitops/demo/application.yaml',P('gitops/demo/application.yaml').read_text(encoding='utf-8'))
a.append('<table><tr><th>Field</th><th>What it means</th></tr>')
for field,meaning in [('metadata.name: demo-nginx','The tile you will open in the Argo CD UI.'),('metadata.namespace: argocd','The Application object lives alongside Argo CD.'),('project: default','Use the built-in project for this small demo; a restricted project is introduced only in the optional chart exercise.'),('source.repoURL','The Git repository Argo reads. It must match your fork if you want your pushes to deploy.'),('targetRevision: main','Watch the main branch.'),('path: gitops/demo/manifests','Render only these workload YAML files, not the Application file itself.'),('destination.server','Use the same Kubernetes cluster where Argo runs.'),('destination.namespace: argocd-demo','Create the demo workload here, separate from Argo and Lab 1.'),('automated.enabled: true','Automatically apply a changed desired state from Git.'),('selfHeal: true','Repair manual drift in the live workload.'),('prune: false','Do not automatically delete resources removed from Git in this beginner lesson.'),('CreateNamespace=true','Create argocd-demo on the first sync.')]:a.append('<tr><td class="field">'+E(field)+'</td><td>'+E(meaning)+'</td></tr>')
a.append('</table>')
code('Save and push the manifests to Git','git add gitops/demo/\ngit commit -m "Prepare my Argo CD demo"\ngit push origin main')
a.append('<p>If the files were already committed unchanged, Git may report “nothing to commit”; continue with the existing pushed files. An uncommitted local edit is invisible to Argo CD. The Application YAML is manually bootstrapped in step 5; there is no parent Application managing it.</p>')
expected('The Git connection is successful, the workload manifests are on the watched branch, and the Application points at the correct repository and folder.')
qa([('Why do I need an Argo Application file?','It binds the repository, revision, manifest path, destination and synchronization policy. Without that link, Argo does not know which configuration should manage which workload.'),('Do I give Argo my GitHub Google-login password?','No. Public Git repositories need no read credential. For private repositories configure supported repository credentials securely; your interactive GitHub login is not a repository password.')]);end()
start(5,'<p>Create only the Application object. It already has auto-sync enabled, so Argo reads Git, creates the namespace, applies the Deployment and Service, and waits for the pods to become healthy. <strong>Do not click Sync to make this demonstration work.</strong></p>')
code('Create the Application; let Argo do the deployment','kubectl apply -f gitops/demo/application.yaml\nkubectl get applications -n argocd\nbash scripts/argocd-demo-check.sh 2')
a.append('<div class="ui"><strong>In the URL:</strong> open Applications → <strong>demo-nginx</strong>. Watch the resource tree show a Deployment, ReplicaSet, two Pods and a Service. Check <strong>Sync status: Synced</strong> and <strong>Health: Healthy</strong>. Details shows your repo, manifest path and resolved Git commit.</div>')
code('Verify the resulting Kubernetes objects','kubectl get deployment,pods,svc -n argocd-demo -L demo-version')
expected('Argo automatically deploys two ready demo-nginx replicas. The workload was created from Git; only its Application object was applied manually.')
qa([('What starts the automatic deployment?','Creating the Application makes Argo compare Git with the cluster. Because automated.enabled is true and the desired resources are missing, Argo automatically syncs them.'),('Synced versus Healthy?','Synced means live configuration matches the desired configuration. Healthy means resource-specific health checks pass. Both should be checked; Synced alone does not prove working pods.')]);end()
start(6,'<p>This is your main classroom demonstration. Keep the demo-nginx resource tree open in the browser. Change the replica count in the <strong>Git manifest</strong>, commit and push, then watch Argo create the third pod. Do not run kubectl scale, kubectl apply on the Deployment, or a manual sync for this demo.</p>')
code('Demo A: Git changes two replicas to three',"sed -i 's/replicas: 2/replicas: 3/' gitops/demo/manifests/deployment.yaml\ngit diff -- gitops/demo/manifests/deployment.yaml\ngit add gitops/demo/manifests/deployment.yaml\ngit commit -m \"Demo: scale NGINX to three through Git\"\ngit push origin main")
a.append('<div class="ui"><strong>Show the audience:</strong> 1. The pushed Git commit. 2. Argo’s new revision and operation in the tile. 3. Desired replicas becomes 3. 4. A third pod appears. Argo polls Git; allow about 1–3 minutes with this lab configuration, including polling jitter and rollout time. You can click <strong>Refresh</strong> to request comparison sooner. <strong>Refresh is not Sync</strong>; auto-sync still performs the deployment.</div>')
code('Verify the result without causing a deployment','bash scripts/argocd-demo-check.sh 3\nkubectl get pods -n argocd-demo')
code('Demo B: change a pod-template configuration label',"sed -i 's/demo-version: v1/demo-version: v2/' gitops/demo/manifests/deployment.yaml\ngit add gitops/demo/manifests/deployment.yaml\ngit commit -m \"Demo: roll out NGINX pod configuration v2\"\ngit push origin main\n# After Argo detects the commit, inspect the new pods:\nkubectl get pods -n argocd-demo -L demo-version")
a.append('<p>Changing the pod-template label triggers a Deployment rollout. The new pods show <code>demo-version=v2</code>. This is a configuration demonstration, not an NGINX page-content change.</p>')
code('Restore the demo baseline through Git',"sed -i 's/replicas: 3/replicas: 2/; s/demo-version: v2/demo-version: v1/' gitops/demo/manifests/deployment.yaml\ngit add gitops/demo/manifests/deployment.yaml\ngit commit -m \"Restore demo to two replicas and configuration v1\"\ngit push origin main\n# Wait for Argo to detect this commit, then:\nbash scripts/argocd-demo-check.sh 2")
expected('Git pushes cause automatic deployment. The final baseline is two replicas with pod label demo-version=v1.')
qa([('Why does my local file edit not deploy?','Argo reads the remote Git branch, not your laptop working directory. You must commit and push to the repository and branch configured in the Application.'),('Refresh versus Sync?','Refresh compares current Git and live state. Sync applies manifests. Auto-sync can act after a refresh; a refresh itself is not a manual deployment request.')]);end()
start(7,'<p>Now demonstrate the other reconciliation trigger: live drift. Git still says two replicas. Temporarily scale the live Deployment to one; self-healing should restore two without a new Git commit. This deliberately differs from the previous Git-change demo.</p>')
code('Introduce live drift and wait for repair','kubectl scale deployment demo-nginx -n argocd-demo --replicas=1\nbash scripts/argocd-demo-check.sh 2\nkubectl get deployment demo-nginx -n argocd-demo')
expected('Argo repairs the manual scale to match the Git value 2. The Git revision did not change.')
qa([('Auto-sync versus self-healing?','Auto-sync deploys a changed desired state from Git. Self-healing additionally corrects live-only changes while the Git revision stays the same.'),('Where should a permanent replica change be made?','In the watched Git manifest. A manual cluster edit can be overwritten by self-healing because it is not the declared desired state.')]);end()
start(8,'<p>The CLI talks to the same Argo server as the browser. Keep the step 2 port-forward running. Log in once, then learn five actions: list, inspect, refresh, wait, history. You do not need a manual sync command for the automatic demo.</p>')
code('Install the matching CLI once, then log in','bash scripts/install-argocd-cli.sh\nexport PATH="$HOME/.local/bin:$PATH"\nargocd login localhost:8090 --username admin --plaintext --grpc-web --skip-test-tls\n# Enter your password interactively.')
a.append('<p><code>--plaintext</code> matches this local HTTP server. <code>--grpc-web</code> uses the compatible API transport, and <code>--skip-test-tls</code> skips an unnecessary HTTPS probe against this local HTTP endpoint. Use localhost:8090 in the same machine’s terminal on either platform, even though KillerCoda’s browser URL looks different.</p>')
code('Five commands you can explain during the demo','argocd app list\nargocd app get demo-nginx\nargocd app get demo-nginx --refresh\nargocd app wait demo-nginx --sync --health --timeout 180\nargocd app history demo-nginx')
a.append('<table><tr><th>Command</th><th>Meaning</th></tr><tr><td>app list</td><td>Show Application sync and health status.</td></tr><tr><td>app get demo-nginx</td><td>Show its repository, destination, resources and status.</td></tr><tr><td>app get demo-nginx --refresh</td><td>Ask Argo to compare the latest Git state sooner.</td></tr><tr><td>app wait ...</td><td>Wait for sync and health; it does not request a sync.</td></tr><tr><td>app history ...</td><td>See which Git revisions were deployed.</td></tr></table>')
a.append('<details><summary>Later: manual sync, diff and repository commands</summary>')
code('Optional inspection and manual operations','argocd repo list\nargocd app diff demo-nginx\n# Only for a separate MANUAL-sync exercise, not the automatic demo:\nargocd app sync demo-nginx')
a.append('</details>')
qa([('Does app wait deploy an Application?','No. It waits for the requested status conditions. Deployment happens through auto-sync or an explicit sync operation.'),('Do I need the CLI to use Argo CD?','No. The Application YAML, browser UI and kubectl are enough for this demo. The CLI is another convenient client for the same server.')]);end()
a.append('<section class="optional"><h2>After the beginner demo: manage today’s three Helm applications</h2><p>This is optional. The main lesson above should work before starting this handover. If you use a fork, first run scripts/gitops-repository.sh with your HTTPS origin URL so the chart Applications and restricted project also reference your fork; review, commit and push those declarations. These Applications read charts/nginx, charts/prometheus and charts/grafana from the same repository and manage the original ingress-lab namespace. They start in manual mode so you can inspect adoption before changing ownership.</p>')
code('Requires Lab 1 workloads: bootstrap and inspect the existing chart Applications','kubectl apply -f gitops/bootstrap/project.yaml\nkubectl apply -f gitops/applications/\n# UI: inspect DIFF for lab-nginx, lab-prometheus and lab-grafana.\nbash scripts/argocd-sync.sh\nbash scripts/argocd-check.sh')
a.append('<p>Argo renders the Helm charts but does not update the original Helm release history. Stop using Helm upgrade/uninstall for these three workloads once Argo manages them. To demonstrate automatic delivery with a chart next, set that Application’s automated.enabled=true and selfHeal=true in its YAML, commit/push and apply the Application declaration once; then change charts/&lt;app&gt;/values.yaml in Git. Changing the Application YAML itself needs reapplication because these Application files are not managed by a parent app.</p>')
qa([('How does Argo deploy an existing Helm chart?','The Application source points to the chart folder. Argo uses Helm to render manifests and then manages those Kubernetes resources; it does not run a normal Helm release installation.'),('Can I keep using Helm and Argo to edit the same workloads?','Choose one active manager. Concurrent Helm upgrades and GitOps reconciliation can overwrite each other. The optional handover freezes the original Helm release records.')]);end()
a.append('<section><h2>When the demo does not deploy</h2><ol><li>Check the Application repoURL, main branch and manifest path.</li><li>Confirm the commit is pushed and its SHA appears in Argo.</li><li>Check that automated.enabled is true and the repository connection succeeds.</li><li>Inspect the Application conditions and pod events.</li></ol>')
code('Read the actual error','kubectl get application demo-nginx -n argocd -o yaml\nkubectl get pods -n argocd-demo\nkubectl get events -n argocd-demo --sort-by=.lastTimestamp')
qa([('OutOfSync versus Degraded?','OutOfSync means desired and live configuration differ. Degraded is a health result. Read both rather than assuming one implies the other.'),('Why can an app show a repository error?','The URL, branch or path may be wrong, access may be denied, or network fetching/rendering may fail. Read the Application condition and repository connection error.'),('Why is a pod Pending?','The scheduler may lack CPU/memory or have node/taint constraints. Inspect kubectl describe pod and cluster capacity; Argo sync success cannot solve missing cluster resources.'),('How do I undo a bad Git change?','Create a new Git revert commit and push it. Argo reconciles the reverted desired state. This keeps the rollback auditable and consistent with auto-sync.')]);end()
a.append('<section><h2>Finish with a predictable demo state</h2><p>Leave Git at two replicas and demo-version v1. Keep the Application auto-syncing for the next session. Stop the UI forward with Ctrl+C when finished. To stop managing the demo without deleting workloads, delete only the Application: it has no resources-finalizer. Do not delete the demo namespace unless you also intend to delete its workload.</p>')
code('Optional: stop managing the demo while preserving its workload','kubectl delete application demo-nginx -n argocd --cascade=orphan')
a.append('<p>References: <a href="https://argo-cd.readthedocs.io/en/stable/getting_started/">Argo CD getting started</a> · <a href="https://argo-cd.readthedocs.io/en/stable/user-guide/auto_sync/">Automatic sync and self-healing</a> · <a href="https://argo-cd.readthedocs.io/en/stable/cli_installation/">CLI installation</a>.</p></section></main><footer>Install → manifests → Git connection → Application → auto-deploy → change Git → observe<span id="status" role="status" aria-live="polite"></span></footer>'+script+'</html>')
P('lab2-argocd.html').write_text(''.join(a),encoding='utf-8',newline='\n')
svg='''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1080 450" role="img"><title>Beginner Argo CD automatic deployment loop</title><defs><marker id="a" markerWidth="10" markerHeight="10" refX="9" refY="3" orient="auto"><path d="M0 0 L9 3 L0 6" fill="none" stroke="#287b7b"/></marker></defs><style>text{font:17px system-ui;fill:#203a42}.b{fill:#fff;stroke:#96bdb4;stroke-width:2}.l{fill:none;stroke:#287b7b;stroke-width:2;marker-end:url(#a)}</style><rect width="1080" height="450" rx="20" fill="#eef6f0"/><text x="25" y="38">ONE DEMO • a Git change causes automatic deployment</text><rect class="b" x="25" y="75" width="260" height="100" rx="12"/><text x="43" y="108">Git repository / main</text><text x="43" y="137">Deployment: replicas 2 → 3</text><text x="43" y="161">Service + pod label v1 → v2</text><path class="l" d="M285 125 H355"/><rect class="b" x="360" y="75" width="305" height="100" rx="12"/><text x="378" y="107">Argo Application</text><text x="378" y="135">repoURL + branch + folder</text><text x="378" y="161">destination + auto-sync policy</text><path class="l" d="M665 125 H735"/><rect class="b" x="740" y="75" width="310" height="100" rx="12"/><text x="758" y="108">Argo CD controller</text><text x="758" y="137">compare → automatic sync</text><text x="758" y="161">watch live state + self-heal</text><path class="l" d="M895 175 V245 H675 V275"/><rect class="b" x="430" y="280" width="490" height="105" rx="12"/><text x="450" y="313">Kubernetes namespace: argocd-demo</text><text x="450" y="342">demo-nginx Service → Deployment → 2 / 3 pods</text><text x="450" y="370">UI resource tree shows the rollout and Git revision</text><text x="30" y="270">Watch in the Argo URL</text><text x="30" y="300">localhost:8090 on desktop</text><text x="30" y="330">generated URL on KillerCoda</text><text x="25" y="425">No manual workload apply or manual Sync is needed after the Git push.</text></svg>'''
P('docs/argocd-beginner-flow.svg').write_text(svg,encoding='utf-8',newline='\n')
print('Rebuilt beginner Lab 2: install first, 8 sequential steps, 22 visible interview answers')
